// Değişkenler
const isim = 'EFEAI';    // Sabit (değiştirilemez)
let yas = 1;              // Değişken

// Şablon literal
console.log(`Merhaba, ${isim}! Yaş: ${yas}`);

// Fonksiyon
const topla = (a, b) => a + b;
console.log(topla(3, 5)); // 8

// Dizi ve map
const sayilar = [1, 2, 3, 4, 5];
const kareler = sayilar.map(x => x ** 2);
console.log(kareler); // [1, 4, 9, 16, 25]

// Eleman seçme
const baslik = document.querySelector('h1');
const butonlar = document.querySelectorAll('.buton');

// İçerik değiştirme
baslik.textContent = 'Yeni Başlık';

// Olay dinleyici
butonlar.forEach(buton => {
    buton.addEventListener('click', (e) => {
        console.log('Tıklandı:', e.target.textContent);
    });
});

async function veriCek(url) {
    try {
        const yanit = await fetch(url);
        const veri = await yanit.json();
        return veri;
    } catch (hata) {
        console.error('Hata:', hata.message);
        return null;
    }
}

// Kullanım
veriCek('https://api.example.com/veri')
    .then(veri => console.log(veri));
